INSERT INTO public.posts (author_id, title, excerpt, content, category, tags, featured)
VALUES
('8df7e606-e32d-4790-9248-9f0726ed1089',
 'آموزش جامع شناسایی و جلوگیری از حملات SQL Injection',
 'SQL Injection هنوز یکی از خطرناک‌ترین آسیب‌پذیری‌های وب است. در این آموزش نحوه کشف، تست اخلاقی و جلوگیری از آن را یاد می‌گیرید.',
 '<h2>SQL Injection چیست؟</h2><p>تزریق SQL زمانی رخ می‌دهد که ورودی کاربر <strong>بدون پاک‌سازی</strong> مستقیماً داخل کوئری دیتابیس قرار بگیرد. مهاجم می‌تواند با این روش اطلاعات را بخواند، تغییر دهد یا حتی حذف کند.</p><h3>یک نمونه کد آسیب‌پذیر</h3><pre><code class="language-php">$id = $_GET["id"];
$result = mysqli_query($conn, "SELECT * FROM users WHERE id = " . $id);</code></pre><p>اگر کاربر مقدار <code>1 OR 1=1</code> را ارسال کند، کل جدول کاربران برگردانده می‌شود.</p><h3>روش صحیح: Prepared Statements</h3><pre><code class="language-php">$stmt = $pdo->prepare("SELECT * FROM users WHERE id = ?");
$stmt->execute([$id]);</code></pre><h3>چک‌لیست دفاعی</h3><ul><li>استفاده همیشگی از <strong>Prepared Statement</strong> یا ORM</li><li>اعمال حداقل دسترسی (Least Privilege) برای کاربر دیتابیس</li><li>استفاده از WAF و لاگ‌گیری کوئری‌های مشکوک</li><li>تست منظم با ابزارهایی مثل <code>sqlmap</code> فقط روی سیستم‌های مجاز</li></ul><blockquote>⚠️ تست نفوذ فقط روی سیستم‌هایی مجاز است که اجازه کتبی مالک را دارید.</blockquote>',
 'آموزش', ARRAY['sql-injection','web-security','owasp'], true),
('8df7e606-e32d-4790-9248-9f0726ed1089',
 'شروع کار با Nmap: اسکن شبکه برای تست نفوذ',
 'Nmap ابزار اصلی هر متخصص امنیت برای شناسایی پورت‌ها و سرویس‌هاست. با دستورات پرکاربرد و نکات حرفه‌ای آن آشنا شوید.',
 '<h2>Nmap چیست؟</h2><p><strong>Nmap</strong> (Network Mapper) یک ابزار متن‌باز برای کشف میزبان‌ها، پورت‌های باز و سرویس‌های در حال اجرا روی شبکه است. اولین قدم در هر <em>تست نفوذ</em> شناسایی (Reconnaissance) است.</p><h3>دستورات پایه</h3><pre><code class="language-bash"># اسکن سریع ۱۰۰ پورت رایج
nmap -F 192.168.1.10

# تشخیص نسخه سرویس‌ها و سیستم‌عامل
nmap -sV -O 192.168.1.10

# اسکن کل یک رنج شبکه
nmap -sn 192.168.1.0/24</code></pre><h3>اسکن مخفی (SYN Scan)</h3><pre><code class="language-bash">sudo nmap -sS -p- -T4 target.local</code></pre><p>این روش اتصال TCP را کامل نمی‌کند و ردپای کمتری در لاگ‌ها می‌گذارد.</p><h3>اسکریپت‌های NSE</h3><ul><li><code>--script vuln</code> برای بررسی آسیب‌پذیری‌های شناخته‌شده</li><li><code>--script http-enum</code> برای کشف مسیرهای وب</li></ul><blockquote>اسکن شبکه‌هایی که مالکشان نیستید بدون مجوز غیرقانونی است. برای تمرین از آزمایشگاه شخصی یا پلتفرم‌هایی مثل HackTheBox استفاده کنید.</blockquote>',
 'هک', ARRAY['nmap','pentest','recon'], false),
('8df7e606-e32d-4790-9248-9f0726ed1089',
 '۱۰ اصل طلایی امنیت حساب‌های کاربری و رمز عبور',
 'بیشتر نفوذها از یک رمز ضعیف یا فیشینگ شروع می‌شوند. با این ۱۰ اصل ساده امنیت حساب‌هایتان را چند برابر کنید.',
 '<h2>چرا امنیت حساب مهم است؟</h2><p>طبق گزارش‌های امنیتی، بخش بزرگی از نفوذها از طریق <strong>رمزهای عبور لو رفته</strong> یا <strong>حملات فیشینگ</strong> انجام می‌شود. خبر خوب این است که با چند عادت ساده می‌توانید ریسک را به‌شدت کاهش دهید.</p><h3>۱۰ اصل طلایی</h3><ol><li>از رمز عبور <strong>حداقل ۱۲ کاراکتری</strong> و ترکیبی استفاده کنید.</li><li>هرگز یک رمز را برای چند سرویس تکرار نکنید.</li><li>از یک <em>Password Manager</em> مثل Bitwarden یا KeePass استفاده کنید.</li><li><strong>احراز هویت دو مرحله‌ای (2FA)</strong> را همه‌جا فعال کنید.</li><li>به‌جای پیامک، از اپلیکیشن‌هایی مثل Google Authenticator استفاده کنید.</li><li>قبل از کلیک، آدرس لینک‌ها را با دقت بررسی کنید.</li><li>سیستم‌عامل و نرم‌افزارها را همیشه به‌روز نگه دارید.</li><li>روی وای‌فای عمومی از VPN معتبر استفاده کنید.</li><li>نشت ایمیل خود را در سایت‌هایی مثل haveibeenpwned بررسی کنید.</li><li>نشست‌های فعال حساب‌ها را دوره‌ای بررسی و موارد ناشناس را خارج کنید.</li></ol><blockquote>💡 در سایت سایبر ۳۲ می‌توانید از بخش «امنیت حساب» احراز هویت دو مرحله‌ای را برای حساب خود فعال کنید.</blockquote>',
 'امنیت', ARRAY['password','2fa','phishing'], false);